export const ROLLUP_VIEWS: Readonly<Record<RollupBy, string>> = Object.freeze({
  object: "v_object_window",
  producer: "v_producer_window",
  strategy: "v_strategy_window",
});

/**
 * The strategy grain (migration 012). `n` is a first-class column here and
 * nowhere else: the consumer weights every cross-strategy mean by it, and a row
 * that states no `n` is weighted 1 rather than dropped — so dropping `n` from
 * this shape would not fail, it would silently let a four-session day outvote a
 * four-thousand-session one. The view sets it to `sessions` and never NULL.
 *
 * `strategy` and `intent` stay NULL rather than becoming "": a node may carry
 * one label and not the other, and the consumer distinguishes an absent label
 * from an empty one.
 */
export function shapeStrategyRow(row: Record<string, unknown>): StrategyRollupRow {
  return {
    strategy: row.strategy === null || row.strategy === undefined ? null : String(row.strategy),
    intent: row.intent === null || row.intent === undefined ? null : String(row.intent),
    day: toDay(row.day),
    n: toNumber(row.n),
    ...shapeMeasures(row),
  };
}
